  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  "Priority" INT NOT NULL DEFAULT 0,
  "ModelID" UUID NULL,
  "VendorID" UUID NULL,
  "ConfigurationID" UUID NULL,
  "Temperature" DECIMAL(3, 2) NULL,
  "TopP" DECIMAL(3, 2) NULL,
  "TopK" INT NULL,
  "MinP" DECIMAL(3, 2) NULL,
  "FrequencyPenalty" DECIMAL(3, 2) NULL,
  "PresencePenalty" DECIMAL(3, 2) NULL,
  "Seed" INT NULL,
  "StopSequences" VARCHAR(1000) NULL,
  "ResponseFormat" VARCHAR(20) NULL,
  "EffortLevel" INT NULL,
  CONSTRAINT "PK_ScopedPromptConfig" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_ScopedPromptConfig_AIPrompt" FOREIGN KEY ("PromptID") REFERENCES __mj."AIPrompt" (
